def get_max_triples(n):
    def helper(a, i, j, k):
        return (a[i] + a[j] + a[k]) % 3 == 0

    a = [i * i - i + 1 for i in range(1, n+1)]

    count = 0
    for i in range(n-2):
        for j in range(i+1, n-1):
            k = j + 1
            while k < n:
                if helper(a, i, j, k):
                    count += 1
                k += 1

    return count
```

